BEGIN; SET LOCAL statement_timeout='1s'; SET LOCAL lock_timeout='500ms';
DO $close$ BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
 OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown')) THEN RAISE EXCEPTION 'ce200_unresolved_work'; END IF;
 UPDATE comparator_strict.execution_budget SET sql_ms_reserved=sql_ms_reserved+1000,read_rows_reserved=read_rows_reserved+25,bytes_reserved=bytes_reserved+16384,write_rows_reserved=write_rows_reserved+1,updated_at=clock_timestamp()
 WHERE project_ref='gkffvigcnsesbaihycay' AND budget_date='2026-09-03' AND approval_reference='CE-200-corpus-v1';
 IF NOT FOUND THEN RAISE EXCEPTION 'ce200_missing_budget'; END IF;
END $close$;
SELECT jsonb_build_object('captured_at',clock_timestamp(),'budget',(SELECT to_jsonb(b) FROM comparator_strict.execution_budget b WHERE budget_date='2026-09-03'),
 'unresolved_jobs',(SELECT count(*) FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown')),
 'control_rows',(SELECT count(*) FROM comparator_strict.execution_control),
 'test_principal_rows',(SELECT count(*) FROM comparator_strict.test_principals),
 'ce200_jobs',(SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT status,count(*) FROM comparator_strict.execution_jobs WHERE operation_key LIKE 'ce200-%' GROUP BY status) s),
 'blocked',(SELECT count(*) FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0),
 'active_older_30s',(SELECT count(*) FROM pg_stat_activity WHERE pid<>pg_backend_pid() AND state='active' AND query_start<clock_timestamp()-interval '30 seconds')) AS evidence;
COMMIT;
